def family_init(ctx):
    ctx.e = ctx.indicator("ema", period=int(ctx.p.ema_n))
    ctx.dx = ctx.indicator("adx", period=int(ctx.p.adx_n))


def _state(ctx, j):
    """The base state on bar j: +1 long-state, -1 short-state, 0 neither."""
    if j < 0:
        return 0
    e = ctx.e[j]
    a = ctx.dx.adx[j]
    if e is None or a is None:
        return 0
    if a < ctx.p.adx_min:
        return 0
    c = ctx.c[j]
    if c > e:
        return 1
    if c < e:
        return -1
    return 0


def signal(ctx, i):
    n = int(ctx.p.n_confirm)
    if n < 1 or i < n:
        return 0
    s = _state(ctx, i)
    if s == 0:
        return 0
    for k in range(1, n):
        if _state(ctx, i - k) != s:
            return 0
    if _state(ctx, i - n) == s:
        return 0
    return s
